#!/usr/bin/env bash
benchmark_run(){ load_config;[[ -f $TF_STATE ]]||die "no active deployment";local role d level=${1:-L1} yes=${2:-};role=$(state_get role);d=$(state_get driver);[[ $role == iran ]]||die "benchmark must run on Iran role";local n bytes;case "$level" in L1)n=1;bytes=65536;;L2)n=50;bytes=262144;;L3)n=250;bytes=262144;;L4)n=1000;bytes=131072;;*)[[ $level =~ ^[0-9]+$ ]]||die "invalid benchmark level";n=$level;bytes=262144;;esac;if ((n>=250))&&[[ $yes != --yes ]];then die "L3+ requires explicit --yes";fi;[[ $(state_get user_verified) == yes ]]||[[ $level == L1 ]]||die "L2+ requires H5 user verification";python3 "$TF_ROOT/benchmark/probe.py" --port "$HEALTH_PORT" --token-file "$TF_HEALTH_TOKEN_FILE" --connections "$n" --bytes "$bytes";load_driver "$d";driver_metrics iran||true;history_add action=benchmark driver="$d" level="$level" connections="$n" result=completed; }
